    private static double calculateTotalAmount(Invoice invoice, Map<String, Play> plays) {
        double totalAmount = 0;
        for (Performance perf : invoice.getPerformances()) {
            Play play = plays.get(perf.getPlayID());
            totalAmount += calculateAmountForPlay(play, perf);
        }
        return totalAmount;
    }

    private static double calculateAmountForPlay(Play play, Performance perf) {
        double thisAmount = 0;
        switch (play.getType()) {
            case "tragedy":
                thisAmount = 40000;
                if (perf.getAudience() > 30) {
                    thisAmount += 1000 * (perf.getAudience() - 30);
