                thisAmount += 300 * perf.getAudience();
                break;
            default:
                throw new IllegalArgumentException("Unknown type: " + play.getType());
        }
        return thisAmount;
    }

    private static int calculateVolumeCredits(Invoice invoice, Map<String, Play> plays) {
